-- The bank's schema in PostgreSQL: the SQLite schema in bank/schema.sql,
-- carried across table for table and column for column.
--
-- Where the types differ, they differ on purpose:
--
--   ids            BIGINT GENERATED BY DEFAULT AS IDENTITY. "By default" so
--                  the migration can keep every original id; the sequences
--                  are then moved past the highest one.
--   money          BIGINT cents. A SQLite INTEGER is 64-bit and a PostgreSQL
--                  INTEGER is 32, so BIGINT is the faithful mapping. Money
--                  stays integer cents -- never NUMERIC, never float.
--   0/1 flags      BOOLEAN. Every stored value was checked to be 0 or 1.
--   REAL           DOUBLE PRECISION. A PostgreSQL REAL is 4 bytes and would
--                  quietly lose precision a SQLite REAL kept.
--   timestamps     TIMESTAMP(0) WITHOUT TIME ZONE, holding exactly the
--                  wall-clock values SQLite held, to the second. Note the
--                  two clocks this inherits: `created_at` columns are UTC,
--                  `occurred_at` and `pin_locked_until` are the server's
--                  local time. Copied as they are, not reinterpreted; making
--                  them one clock is a separate, deliberate change.
--   'MM/YY'        TEXT. A card's validity is printed text, not a date.
--
-- Nothing is added that SQLite did not have, with one exception: SQLite
-- gives every table a hidden `rowid`, and `disputes()` and `handoffs()`
-- order by it to keep rows from the same second in the order they were
-- written. PostgreSQL has no hidden row number, so `seq` makes it explicit
-- and the migration copies SQLite's values into it.

CREATE TABLE accounts (
    name          TEXT PRIMARY KEY,
    balance_cents BIGINT NOT NULL CHECK (balance_cents >= 0)
);

-- Who money may be sent to. Separate from accounts on purpose: an account
-- name is not a payee, and "send 500 to savings" must not debit checking
-- and credit nobody.
CREATE TABLE payees (
    name TEXT PRIMARY KEY
);

CREATE TABLE bills (
    name         TEXT PRIMARY KEY,
    amount_cents BIGINT NOT NULL,
    paid         BOOLEAN NOT NULL DEFAULT FALSE,
    category     TEXT NOT NULL DEFAULT 'bills',
    due_day      INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE cards (
    last4            TEXT PRIMARY KEY,
    account          TEXT NOT NULL REFERENCES accounts (name),
    frozen           BOOLEAN NOT NULL DEFAULT FALSE,
    kind             TEXT NOT NULL DEFAULT 'debit',
    holder           TEXT NOT NULL DEFAULT '',
    number           TEXT NOT NULL DEFAULT '',
    valid_from       TEXT NOT NULL DEFAULT '',
    valid_to         TEXT NOT NULL DEFAULT '',
    pin_hash         TEXT NOT NULL DEFAULT '',
    pin_salt         TEXT NOT NULL DEFAULT '',
    pin_failures     INTEGER NOT NULL DEFAULT 0,
    -- NULL when the card is not locked. SQLite stored '' for that, which a
    -- timestamp column cannot hold, so this is the one column that is
    -- nullable here and NOT NULL there.
    pin_locked_until TIMESTAMP(0),
    ecommerce        BOOLEAN NOT NULL DEFAULT TRUE,
    retail           BOOLEAN NOT NULL DEFAULT TRUE,
    atm              BOOLEAN NOT NULL DEFAULT TRUE
);

-- The ledger. Money out is negative. Every balance change writes a row in
-- the same transaction as the change, so an interruption leaves neither.
CREATE TABLE transactions (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account     TEXT NOT NULL REFERENCES accounts (name),
    merchant    TEXT NOT NULL,
    cents       BIGINT NOT NULL,
    occurred_at TIMESTAMP(0) NOT NULL
);

CREATE INDEX idx_tx_occurred ON transactions (occurred_at);

-- No foreign key to transactions, matching SQLite. `reset` deletes the
-- ledger and keeps the disputes, so a key here would make reset fail.
CREATE TABLE disputes (
    reference      TEXT PRIMARY KEY,
    seq            BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
    transaction_id BIGINT NOT NULL UNIQUE,
    merchant       TEXT NOT NULL,
    amount_cents   BIGINT NOT NULL,
    occurred_at    TIMESTAMP(0) NOT NULL,
    reason         TEXT NOT NULL,
    note           TEXT,
    status         TEXT NOT NULL DEFAULT 'open',
    created_at     TIMESTAMP(0) NOT NULL DEFAULT date_trunc('second', now() AT TIME ZONE 'UTC')
);

CREATE TABLE handoffs (
    reference  TEXT PRIMARY KEY,
    seq        BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
    session_id TEXT NOT NULL,
    turn_index INTEGER NOT NULL,
    reason     TEXT NOT NULL,
    note       TEXT,
    created_at TIMESTAMP(0) NOT NULL DEFAULT date_trunc('second', now() AT TIME ZONE 'UTC')
);

CREATE INDEX idx_handoffs_session ON handoffs (session_id);

-- The audit log: what was said, which tools ran, whether the guard fired.
-- It survives a reset; it is the record.
CREATE TABLE turns (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id TEXT NOT NULL,
    turn_index INTEGER NOT NULL,
    user_text  TEXT,
    bot_text   TEXT,
    tool_calls TEXT,
    guard_hit  BOOLEAN NOT NULL DEFAULT FALSE,
    suppressed TEXT,
    latency_ms DOUBLE PRECISION,
    created_at TIMESTAMP(0) NOT NULL DEFAULT date_trunc('second', now() AT TIME ZONE 'UTC')
);

CREATE INDEX idx_turns_session ON turns (session_id, turn_index);
